"""Route reference recognizer and canonicalizer for Vietnamese highways and roads."""

from __future__ import annotations

import functools
import re
from dataclasses import dataclass
from typing import Any, Literal

from .text_utils import collapse_whitespace, normalize_ascii, normalize_unicode_nfkc

RouteType = Literal[
    "national",
    "provincial",
    "expressway",
    "district",
    "ring_road",
    "bypass",
    "unknown",
]

__all__ = [
    "RouteType",
    "RouteRefInfo",
    "is_route_ref",
    "is_highway_km_post",
    "parse_route_ref",
    "canonicalize_route_ref",
]

from ..grammar.thoroughfare import (
    BUILDING_RESIDENTIAL_CTX_RE as _BUILDING_RESIDENTIAL_CTX_RE,
)
from ..grammar.thoroughfare import (
    CANONICAL_LABELS as _CANONICAL_LABELS,
)
from ..grammar.thoroughfare import (
    COMPACT_PREFIX_NO_DOT_RE as _COMPACT_PREFIX_NO_DOT_RE,
)
from ..grammar.thoroughfare import (
    COMPACT_PREFIX_RE as _COMPACT_PREFIX_RE,
)
from ..grammar.thoroughfare import (
    CT_TOWER_BLOCK_NUMBER_RE as _CT_TOWER_BLOCK_NUMBER_RE,
)
from ..grammar.thoroughfare import (
    DASH_NORMALIZATION_RE as _DASH_NORMALIZATION_RE,
)
from ..grammar.thoroughfare import (
    DIGIT_MATCH_RE as _DIGIT_MATCH_RE,
)
from ..grammar.thoroughfare import (
    EXPRESSWAY_INDICATOR_RE as _EXPRESSWAY_INDICATOR_RE,
)
from ..grammar.thoroughfare import (
    KM_POST_MARKER_RE as _KM_POST_MARKER_RE,
)
from ..grammar.thoroughfare import (
    KM_PREFIX_RE as _KM_PREFIX_RE,
)
from ..grammar.thoroughfare import (
    PREFIX_RULES as _PREFIX_RULES,
)
from ..grammar.thoroughfare import (
    ROUTE_FALSE_POSITIVE_BLOCKLIST as _FALSE_POSITIVE_BLOCKLIST,
)
from ..grammar.thoroughfare import (
    ROUTE_QUALIFIER_CANONICAL_MAP as _ROUTE_QUALIFIER_CANONICAL_MAP,
)
from ..grammar.thoroughfare import (
    ROUTE_SUFFIX_QUALIFIER_RE as _ROUTE_SUFFIX_QUALIFIER_RE,
)
from ..grammar.thoroughfare import (
    STANDALONE_ROUTE_PREFIX_STRIP_RE as _STANDALONE_ROUTE_PREFIX_STRIP_RE,
)
from ..grammar.thoroughfare import (
    PrefixRule as _PrefixRule,
)


@dataclass(slots=True, frozen=True)
class RouteRefInfo:
    """Decomposed route reference metadata."""

    raw: str
    prefix: str
    number: str
    route_type: RouteType
    canonical_name: str
    is_valid: bool
    qualifier: str | None = None

    @property
    def street_type(self) -> str:
        """Route type label (e.g. 'Quốc Lộ', 'Đường Tỉnh')."""
        if not self.is_valid:
            return ""
        name = self.canonical_name
        if self.qualifier and name.endswith(f" {self.qualifier}"):
            name = name[: -(len(self.qualifier) + 1)]
        if self.number and name.endswith(f" {self.number}"):
            name = name[: -(len(self.number) + 1)]
        return name or self.canonical_name


def _normalize_number(number: str) -> str:
    """Uppercase optional alphabetic suffixes while preserving digits and hyphens."""
    if not number:
        return number
    norm = _DASH_NORMALIZATION_RE.sub("-", number.strip())
    return norm.upper()


def _build_canonical_name(form: str, number: str, qualifier: str | None = None) -> str:
    label = _CANONICAL_LABELS[form]
    base = f"{label} {_normalize_number(number)}"
    if qualifier:
        return f"{base} {qualifier}"
    return base


def _split_compact_prefix(text: str) -> str:
    """Insert a space between compact route prefixes and following digits (e.g. QL1A -> QL 1A)."""
    split_dot = _COMPACT_PREFIX_RE.sub(r"\1 ", text)
    return _COMPACT_PREFIX_NO_DOT_RE.sub(r"\1 ", split_dot)


def _invalid_info(raw: str) -> RouteRefInfo:
    return RouteRefInfo(
        raw=raw,
        prefix="",
        number="",
        route_type="unknown",
        canonical_name="",
        is_valid=False,
        qualifier=None,
    )


def _is_bare_ct_prefix_match(match: re.Match[str], rule: _PrefixRule) -> bool:
    if rule.canonical_form != "cao_toc":
        return False
    return normalize_ascii(match.group("prefix")) == "ct"


def _is_standalone_route_ref(working_ascii: str, match: re.Match[str]) -> bool:
    before = working_ascii[: match.start()].strip()
    after = working_ascii[match.end() :].strip()
    before = _STANDALONE_ROUTE_PREFIX_STRIP_RE.sub("", before).strip()
    return not before and not after


def _is_ct_tower_block_number(number: str) -> bool:
    """CT1 / CT12A-style residential tower blocks, not zero-padded expressway codes."""
    norm = number.upper().strip()
    if not norm or norm.startswith("0"):
        return False
    m = _CT_TOWER_BLOCK_NUMBER_RE.fullmatch(norm)
    if not m:
        return False
    digits = int(m.group(1))
    letter = m.group(2)
    if letter is not None and digits <= 13:
        return True
    return digits <= 9 and letter is None


def _accept_bare_ct_expressway(working_ascii: str, match: re.Match[str], number_raw: str) -> bool:
    if _BUILDING_RESIDENTIAL_CTX_RE.search(working_ascii):
        return False
    if _EXPRESSWAY_INDICATOR_RE.search(working_ascii):
        return True
    if _is_standalone_route_ref(working_ascii, match):
        return not _is_ct_tower_block_number(number_raw)
    return False


def _resolve_suffix_qualifier(m_qual: re.Match[str]) -> str | None:
    raw = (m_qual.group("paren_q") or m_qual.group("bare_q") or "").strip().lower()
    raw = collapse_whitespace(raw)
    if not raw:
        return None
    if canon := _ROUTE_QUALIFIER_CANONICAL_MAP.get(raw):
        return canon
    if raw.startswith("nhanh "):
        parts = raw.split(maxsplit=1)
        return f"nhánh {parts[1].upper()}" if len(parts) > 1 else "nhánh"
    return None


def _extract_route_qualifier(working_ascii: str, match: re.Match[str]) -> tuple[bool, str | None]:
    """Extract and validate route qualifier from pre-match or trailing tail.

    Returns (is_valid, canonical_qualifier).
    """
    tail = working_ascii[match.end() :].strip()
    pre_q = match.groupdict().get("pre_qualifier")

    qualifier: str | None = None
    if tail:
        if not (m_qual := _ROUTE_SUFFIX_QUALIFIER_RE.match(tail)) or not (
            qualifier := _resolve_suffix_qualifier(m_qual)
        ):
            return False, None
    elif pre_q:
        pre_norm = collapse_whitespace(pre_q.strip().lower())
        qualifier = _ROUTE_QUALIFIER_CANONICAL_MAP.get(pre_norm, "tuyến tránh")

    return True, qualifier


@functools.lru_cache(maxsize=8192)
def parse_route_ref(text: str) -> RouteRefInfo:
    """Parse a Vietnamese route reference into structured metadata."""
    if not isinstance(text, str):
        return _invalid_info(str(text) if text is not None else "")

    raw = text.strip()
    if not raw or _DIGIT_MATCH_RE.search(raw) is None:
        return _invalid_info(raw)

    normalized = collapse_whitespace(normalize_unicode_nfkc(raw))
    ascii_norm = normalize_ascii(normalized)

    if ascii_norm in _FALSE_POSITIVE_BLOCKLIST:
        return _invalid_info(raw)

    working = collapse_whitespace(_KM_PREFIX_RE.sub("", normalized).strip())
    if not working:
        return _invalid_info(raw)

    working_ascii = collapse_whitespace(_split_compact_prefix(normalize_ascii(working)))

    for rule in _PREFIX_RULES:
        match = rule.pattern.search(working_ascii)
        if not match:
            continue

        number_raw = match.group("number")
        if _is_bare_ct_prefix_match(match, rule) and not _accept_bare_ct_expressway(
            working_ascii, match, number_raw
        ):
            continue

        is_tail_valid, qualifier = _extract_route_qualifier(working_ascii, match)
        if not is_tail_valid:
            continue

        number = _normalize_number(number_raw)
        canonical_name = _build_canonical_name(rule.canonical_form, number, qualifier)

        return RouteRefInfo(
            raw=raw,
            prefix=rule.prefix_code,
            number=number,
            route_type=rule.route_type,
            canonical_name=canonical_name,
            is_valid=True,
            qualifier=qualifier,
        )

    return _invalid_info(raw)


def is_route_ref(text: str) -> bool:
    """Return True when *text* is a recognized route reference."""
    return parse_route_ref(text).is_valid


def is_highway_km_post(text: str | Any) -> bool:
    """Return True when *text* contains a bare kilometer-post marker (km\\d+).

    A km-post marker indicates that house numbers along the segment follow
    highway chainage rather than a monotonic street sequence, so linear
    corridor monotonicity checks must be suppressed.

    Unlike :func:`is_route_ref`, this function does NOT require a route-type
    prefix (QL, CT, etc.) — it detects the raw ``km\\s*\\d+`` pattern.

    Parameters
    ----------
    text : str
        Raw street name or address fragment to examine.

    Returns
    -------
    bool
        True if a km-post marker is detected anywhere in *text*.
    """
    if not isinstance(text, str):
        return False
    return bool(_KM_POST_MARKER_RE.search(text))


def canonicalize_route_ref(text: str | Any) -> str:
    """Return canonical route name, or the original text when not a route ref."""
    if not isinstance(text, str):
        return ""
    info = parse_route_ref(text)
    if info.is_valid:
        return info.canonical_name
    return text.strip()

